88	// A readable default from a statement filename: no extension, dates, long numbers or separators.
89	export function friendlyAccountName(filename: string): string {
90	  const name = filename.replace(/\.(csv|xlsx)$/i, "")
91	    .replace(/(?<![A-Z0-9])[A-Z]{2}\d{2}[A-Z0-9]{10,30}|(?<!\d)\d{9,}(?!\d)/gi, maskAccountNumber)
92	    .replace(/(?<!\d)\d{4}[-_.]?\d{2}(?:[-_.]?\d{2})?(?!\d)/g, " ")
93	    .replace(/[_\-.]+/g, " ").replace(/\s+/g, " ").trim();
94	  return Array.from(name).slice(0, 100).join("") || "Imported account";
95	}
