144	export function proposeStatementTimezones(rows: SourceRow[], mapping: ImportMapping, workspaceTimezone = "Europe/Berlin"): ImportMapping {
145	  const naive = rows.some(row => /[ T]\d{2}:\d{2}:\d{2}(?:\.\d{1,3})?$/.test(row[mapping.dateColumn]?.trim() ?? ""));
146	  return { ...mapping, calendarTimezone: workspaceTimezone,
147	    ...(naive ? { timestampTimezone: mapping.timestampTimezone ?? workspaceTimezone,
148	      timestampTimezoneConfirmed: mapping.timestampTimezoneConfirmed ?? false } : {}) };
