174	function cellText(cell: ExcelJS.Cell, preserveTime = false): string {
175	  const raw = cell.value;
176	  const value = raw && typeof raw === "object" && "result" in raw ? raw.result : raw;
177	  if (value == null) return "";
178	  if (value instanceof Date) {
179	    const iso = value.toISOString();
180	    const format = (cell.numFmt ?? "").replace(/"[^"]*"|\\.|\[[^\]]*\]/g, "");
181	    const hasTime = /h|s|AM\/PM/i.test(format) || value.getUTCHours() !== 0 || value.getUTCMinutes() !== 0 || value.getUTCSeconds() !== 0 || value.getUTCMilliseconds() !== 0;
182	    return preserveTime && hasTime ? iso.replace(/Z$/, "").replace(/\.000$/, "") : iso.slice(0, 10);
183	  }
184	  if (typeof value === "object" && "result" in value) return String(value.result ?? "");
185	  if (typeof value === "object") return cell.text;
186	  return String(value);
187	}
