209	    sharedHeaders = headers;
210	    for (let rowNumber = table.headerRow + 1; rowNumber <= table.endRow; rowNumber++) {
211	      const row = table.sheet.getRow(rowNumber);
212	      if (!row.hasValues) continue;
213	      const values: SourceRow = Object.fromEntries(headers.map((name, index) => {
214	        return [name, cellText(row.getCell(index + 1), !!input)];
215	      }));
216	      if (input && row.cellCount > headers.length) {
217	        const extra = Array.from({length: row.cellCount - headers.length}, (_, index) => {
218	          const cell = row.getCell(headers.length + index + 1);
219	          return {columnNumber: headers.length + index + 1, type: cell.type, value: cell.value, numberFormat: cell.numFmt};
220	        });
221	        if (extra.some(cell => cell.value !== null && cell.value !== "")) {
222	          values[csvIssueColumn] = "TooManyFields";
223	          values[csvExtraColumn] = JSON.stringify(extra);
224	        }
225	      }
226	      if (input) values.__moneo_csv_xlsx_source = JSON.stringify({ version: "xlsx-scope-v1", sheetId: table.sheet.id, sheetName: table.sheet.name, sheetState: table.sheet.state, headerRow: table.headerRow, rowNumber,
227	        cells: Object.fromEntries(headers.map((name, index) => { const cell = row.getCell(index + 1); return [name, { type: cell.type, value: cell.value, numberFormat: cell.numFmt }]; })) });
228	      rows.push(values);
229	    }
230	  }
231	  assertStorageCompatible(rows);
232	  return rows;
233	}
