257	export function validateMapping(input: unknown, rows: SourceRow[]): ImportMapping {
258	  const mapping = mappingSchema.parse(input);
259	  // Exclusions and corrections never rewrite incompatible original evidence.
260	  assertStorageCompatible(rows);
261	  assertStorageCompatible(mapping);
262	  if (!rows.length) throw new Error("File has no data rows");
263	  const headers = Object.keys(rows[0]).filter(header => !header.startsWith("__moneo_csv_"));
264	  const decisions = new Set<number>();
265	  for (const decision of mapping.rowDecisions ?? []) {
266	    if (decision.rowNumber > rows.length + 1 || decisions.has(decision.rowNumber)) throw new Error("Invalid or duplicate source row decision");
267	    decisions.add(decision.rowNumber);
268	    if (decision.action === "correct" && Object.keys(decision.values).some(key => !Object.hasOwn(rows[decision.rowNumber - 2], key)))
269	      throw new Error("Correction contains an unknown source column");
270	  }
271	  for (const column of [mapping.dateColumn, mapping.descriptionColumn, mapping.amountColumn,
272	    mapping.debitColumn, mapping.creditColumn, mapping.currencyColumn, mapping.balanceColumn,
273	    mapping.merchantColumn, mapping.categoryColumn, mapping.externalIdColumn, mapping.statusColumn,
274	    mapping.accountColumn, mapping.productColumn, mapping.typeColumn, mapping.feeColumn]) {
275	    if (column && !headers.includes(column)) throw new Error(`Unknown column: ${column}`);
276	  }
277	  for (const [name, column] of [["product", mapping.productColumn], ["account", mapping.accountColumn]]) {
278	    const detected = headers.find(header => header.trim().toLowerCase() === name);
279	    if (detected && !column) throw new Error(`Review account routing: map ${detected}`);
280	  }
281	  const detectedStatus = headers.find(header => /^(status|state)$/i.test(header.trim()));
282	  if (detectedStatus && !mapping.statusColumn) throw new Error(`Review source status: map ${detectedStatus}`);
283	  return mapping;
284	}
