292	// Suggestions are displayed in the preview; confirmation validates the exact reviewed routes.
293	export function proposeAccountRoutes(rows: SourceRow[], input: unknown): ImportMapping {
294	  const mapping = mappingSchema.parse(input);
295	  const headers = Object.keys(rows[0] ?? {});
296	  const accountColumn = mapping.accountColumn ?? headers.find(header => header.trim().toLowerCase() === "account");
297	  const productColumn = mapping.productColumn ?? headers.find(header => header.trim().toLowerCase() === "product");
298	  const statusColumn = mapping.statusColumn ?? headers.find(header => /^(status|state)$/i.test(header.trim()));
299	  if (mapping.accountRoutes || (!accountColumn && !productColumn)) return { ...mapping, accountColumn, productColumn, statusColumn };
300	  const routes = new Map<string, NonNullable<ImportMapping["accountRoutes"]>[number]>();
301	  for (const row of rows) {
302	    const accountValue = accountColumn ? row[accountColumn]?.trim() : undefined;
303	    const productValue = productColumn ? row[productColumn]?.trim() : undefined;
304	    const currencyCode = (mapping.currencyColumn ? row[mapping.currencyColumn] : mapping.currencyCode)?.trim().toUpperCase();
305	    // Invalid source currencies remain quarantined observations, rather than
306	    // poisoning the route proposal for valid neighboring rows.
307	    if (!/^[A-Z]{3}$/.test(currencyCode ?? "")) continue;
308	    const key = JSON.stringify([accountValue, productValue, currencyCode]);
309	    routes.set(key, { accountValue, productValue, currencyCode,
310	      accountName: Array.from([mapping.accountName, accountValue && maskAccountNumber(accountValue), productValue].filter(Boolean).join(" · ")).slice(0, 96).join("") });
311	  }
312	  return mappingSchema.parse({ ...mapping, accountColumn, productColumn, statusColumn, accountRoutes: distinctRouteNames([...routes.values()]) });
313	}
