349	function parseDate(input: string, format: ImportMapping["dateFormat"]): string {
350	  const value = input.trim();
351	  const match = format === "iso"
352	    ? /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,3})?(?:Z|[+-]\d{2}:[0-5]\d)?)?$/.exec(value)
353	    : /^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/.exec(value);
354	  if (!match) throw new Error(`Invalid date: ${input}`);
355	  const [year, month, day] = format === "iso"
356	    ? [Number(match[1]), Number(match[2]), Number(match[3])]
357	    : [Number(match[3]), Number(match[format === "dmy" ? 2 : 1]), Number(match[format === "dmy" ? 1 : 2])];
358	  const date = new Date(Date.UTC(year, month - 1, day));
359	  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day)
360	    throw new Error(`Invalid date: ${input}`);
361	  return date.toISOString().slice(0, 10);
362	}
363	
364	function parseTimestamp(value: string, timeZone?: string): string | undefined {
365	  const match = /^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{2}):(\d{2}):(\d{2})(?:\.\d{1,3})?(Z|[+-]\d{2}:\d{2})?$/.exec(value.trim());
366	  if (!match) return undefined;
367	  if (match[7]) {
368	    const instant = new Date(value.trim().replace(" ", "T"));
369	    if (!Number.isFinite(instant.getTime())) throw new Error("Invalid timestamp offset");
370	    return instant.toISOString();
371	  }
372	  // Legacy mappings keep their original posting date; new confirmations require the timezone.
373	  if (!timeZone) return undefined;
374	  return reviewedLocalTimestamp(value, timeZone);
375	}
