cat > scripts/.diag.tmp.mjs <<'EOF'
import postgres from "postgres";
import { readFileSync } from "node:fs";
const { id, email } = JSON.parse(readFileSync(".qa/e2e-auth-user.json", "utf8"));
if (!/^qa-\d+@example\.test$/.test(email)) throw new Error("not a QA user");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
await db.begin(async tx => {
  const [u] = await tx`select raw_user_meta_data->>'qa_test' as qa from auth.users where id=${id}`;
  if (u?.qa !== "e2e-auth") throw new Error("user is not tagged e2e-auth");
  const ws = (await tx`select id from public.workspaces where owner_id=${id}`).map(r => r.id);
  await tx`set local session_replication_role = replica`;
  const cols = await tx`select table_name, column_name from information_schema.columns c join information_schema.tables t using (table_schema, table_name)
    where table_schema='public' and t.table_type='BASE TABLE' and column_name in ('workspace_id','actor_id','user_id','owner_id','created_by')`;
  let n = 0;
  for (const { table_name, column_name } of cols) {
    const r = await tx.unsafe(`delete from public."${table_name}" where "${column_name}"::text = any($1::text[])`, [[id, ...ws]]);
    n += r.count;
  }
  await tx`delete from public.workspaces where id = any(${ws})`;
  await tx`delete from auth.users where id=${id}`;
  console.log(`deleted QA user, ${ws.length} workspace(s), ${n} rows`);
});
await db.end();
EOF
